#!/usr/bin/env bash
# Rebuilds the standalone SDBL parser bundle (sdbl_parse.js) from the
# query_console_vscode project via esbuild. The bundle is self-contained (no npm
# install at runtime) and is invoked from the Python analyzer through `node`.
#
# Parser source: query_console_vscode/src/core/query/sdblParser.ts
#   parseBatch(text) -> BatchDocument (structural query model, no metadata).
#
# Path to the query_console_vscode repository: QUERY_CONSOLE_REPO environment
# variable, otherwise - the standard location next to the project (../../.../query_console_vscode).
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"

repo="${QUERY_CONSOLE_REPO:-}"
if [ -z "$repo" ]; then
  # projects/ nearby: vendor -> scripts -> query-analyze -> skills -> .claude ->
  # template -> ai_template -> projects
  cand="$HERE/../../../../../../../query_console_vscode"
  if [ -d "$cand" ]; then repo="$(cd "$cand" && pwd)"; fi
fi

if [ -z "$repo" ] || [ ! -f "$repo/src/core/query/sdblParser.ts" ]; then
  echo "Не найден query_console_vscode. Укажите путь: QUERY_CONSOLE_REPO=/путь/к/query_console_vscode $0" >&2
  exit 1
fi
repo="$(cd "$repo" && pwd)"

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
cat > "$tmp/entry.ts" <<EOF
// Auto-generated by build-parser.sh. Reads query text from stdin, prints
// the structural model (BatchDocument) as JSON. Parse errors -> {"error": "..."}.
import { parseBatch } from '$repo/src/core/query/sdblParser';
let text = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (d) => (text += d));
process.stdin.on('end', () => {
  try {
    process.stdout.write(JSON.stringify(parseBatch(text)));
  } catch (e) {
    process.stdout.write(JSON.stringify({ error: String(e) }));
  }
});
EOF

( cd "$repo" && npx esbuild "$tmp/entry.ts" --bundle \
  --outfile="$HERE/sdbl_parse.js" --platform=node --format=cjs )

echo "Собрано: $HERE/sdbl_parse.js (из $repo)"
